import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"CoreLib 动作","description":"","frontmatter":{},"headers":[],"relativePath":"modules/attribute/corelib-actions.md","filePath":"modules/attribute/corelib-actions.md","lastUpdated":0}`),a={name:`modules/attribute/corelib-actions.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="corelib-动作" tabindex="-1">CoreLib 动作 <a class="header-anchor" href="#corelib-动作" aria-label="Permalink to “CoreLib 动作”">​</a></h1><p>EmakiAttribute 启用后会向 CoreLib 动作注册表追加属性、资源、标签和同步相关段。它们可以写在支持 CoreLib 管道的配置节点中，例如 Forge/Strengthen/Cooking/Skills/Item 的动作列表、CoreLib 管道模板，或由其他插件通过 CoreLib 管道引擎触发。</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>本页只记录 EmakiAttribute 注册的段；CoreLib 自带的消息、命令、经济、物品等通用段见 <a href="./../corelib/actions.html">CoreLib 动作系统</a>。当前段 ID 只使用下表中的规范名，不再提供历史别名入口。旧的 <code>attributedamage</code> 现在写作 <code>attribute_damage</code>；其余段的 id 未变。</p></div><p>「作用于谁」由 source 决定：作用于执行者自己写 <code>self</code>，指定玩家用 <code>player_by_name</code>。</p><h2 id="段-id-速查" tabindex="-1">段 ID 速查 <a class="header-anchor" href="#段-id-速查" aria-label="Permalink to “段 ID 速查”">​</a></h2><table tabindex="0"><thead><tr><th>段 ID</th><th>用途</th><th>目标要求</th></tr></thead><tbody><tr><td><code>attribute_damage</code></td><td>对目标造成一次 Attribute 自定义伤害。</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_add</code></td><td>给目标添加限时属性修饰。</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_set</code></td><td>设置目标的限时属性修饰。</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_remove</code></td><td>清理目标指定 <code>effect_id</code> 效果组内的全部限时属性。</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_resource_add</code></td><td>增加目标指定资源当前值。</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_resource_set</code></td><td>设置目标指定资源当前值。</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_resource_remove</code></td><td>扣除目标指定资源当前值。</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_resource_consume</code></td><td>消耗目标指定资源。</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_tag_add</code></td><td>按属性标签批量添加限时属性。</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_tag_remove</code></td><td>按属性标签移除限时属性。</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_tag_clear</code></td><td>按属性标签清理限时属性。</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_sync</code></td><td>同步目标或全部在线玩家的属性与资源状态。</td><td><code>OPTIONAL</code></td></tr><tr><td><code>attribute_refresh</code></td><td>刷新 Attribute 缓存，并同步目标或全部在线玩家。</td><td><code>OPTIONAL</code></td></tr></tbody></table><p>除两个同步段外，<code>attribute_damage</code> 与资源段只接受玩家目标；限时属性与标签段接受任意生物实体（含非玩家生物），非生物目标会跳过。<code>attribute_damage</code> 的目标要求虽声明为 <code>REQUIRED_ENTITY</code>，但实现只处理 <code>Player</code>，指向非玩家生物时以 <code>not_player</code> 跳过、不造成伤害。</p><div class="warning custom-block"><p class="custom-block-title">升级须知：限时属性行为变化</p><p>两条对既有配置可见的变化：</p><ol><li><strong>标签入口的复合效果 ID 已消失。</strong> <code>attribute_tag_add effect_prefix=poison</code> 过去会写出 <code>poison:physical_attack</code>、<code>poison:movement_speed</code> 等一条条互不相干的顶层记录，现在改为全部归入 <code>poison</code> <strong>一个效果组</strong>。因此按 <code>poison:physical_attack</code> 这类复合 ID 精确删除的旧配置会失效，需改为 <code>attribute_remove effect_id=poison</code>；反过来，过去删不掉任何东西的 <code>attribute_remove effect_id=poison</code> 现在才真正生效。</li><li><strong>多个效果组对同一属性 SET 时的胜者已确定。</strong> 过去由内部哈希表迭代顺序决定，同样的配置可能得到不同结果，也可能随扩容变化；现在固定为<strong>最后写入的那一条生效</strong>（按内部单调序号取最大者），重复运行结果稳定。<code>/ea trace</code> 会把被覆盖的那条显示为「被更高 revision 覆盖」。</li></ol><p>单属性配置不受影响，行为逐字不变。</p></div><h2 id="attribute-damage" tabindex="-1">attribute_damage <a class="header-anchor" href="#attribute-damage" aria-label="Permalink to “attribute_damage”">​</a></h2><p>对目标造成一次 Attribute 伤害。和 CoreLib 内置的 <code>damage</code> 不同，这个段走 EmakiAttribute，所以模块的伤害类型、抗性与战斗快照都会生效。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>amount</code></td><td>DOUBLE</td><td>是</td><td>—</td><td>基础伤害值。</td></tr><tr><td><code>type</code></td><td>STRING</td><td>否</td><td><code>&quot;&quot;</code></td><td>伤害类型 ID；留空使用 EmakiAttribute 的默认伤害类型。</td></tr><tr><td><code>cause</code></td><td>STRING</td><td>否</td><td><code>CUSTOM</code></td><td>Bukkit <code>EntityDamageEvent.DamageCause</code>，如 <code>CUSTOM</code>、<code>MAGIC</code>、<code>ENTITY_ATTACK</code>。</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_damage amount=25 type=physical cause=CUSTOM&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;looking_at range=15 | attribute_damage amount=40 type=spell cause=MAGIC&#39;</span></span></code></pre></div><p><code>cause</code> 写成无法识别的值时以 <code>INVALID_CONFIG</code> 失败，不会退回一个错误的 cause 继续打伤害；空值等同 <code>CUSTOM</code>。伤害被模块规则拒绝时以 <code>REJECTED</code> 失败。成功时输出 <code>damage_type</code>。</p><h2 id="限时属性" tabindex="-1">限时属性 <a class="header-anchor" href="#限时属性" aria-label="Permalink to “限时属性”">​</a></h2><p><code>effect_id</code> 是<strong>效果组 ID</strong>，不是单条效果的 ID。同一个 <code>effect_id</code> 下可以放多个属性，它们互不覆盖、一起到期、也能被 <code>attribute_remove</code> 一次整组清掉。<code>attribute_add</code> 与 <code>attribute_set</code> 决定组内<strong>该属性</strong>这一条是加算还是覆盖，这也是两者分成独立段而不是共用一个 mode 参数的原因。</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_add effect_id=buff_strength attribute=physical_attack value=10 duration_ticks=200t&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_add effect_id=buff_strength attribute=physical_crit_rate value=5 duration_ticks=200t&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_remove effect_id=buff_strength&#39;</span></span></code></pre></div><p>上例的两条 <code>attribute_add</code> 进同一组，<code>attribute_remove</code> 一次清掉两个属性。</p><h3 id="attribute-add-attribute-set" tabindex="-1">attribute_add / attribute_set <a class="header-anchor" href="#attribute-add-attribute-set" aria-label="Permalink to “attribute_add / attribute_set”">​</a></h3><p>两个段参数相同。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>effect_id</code></td><td>STRING</td><td>是</td><td>—</td><td>效果组 ID；复用同一个 ID 会把多个属性归入同一组。</td></tr><tr><td><code>attribute</code></td><td>STRING</td><td>是</td><td>—</td><td>属性 ID；未注册时以 <code>INVALID_CONFIG</code> 失败。</td></tr><tr><td><code>value</code></td><td>DOUBLE</td><td>是</td><td>—</td><td>修饰值；<code>NaN</code> 与 <code>±Inf</code> 以 <code>INVALID_CONFIG</code> 失败。</td></tr><tr><td><code>duration_ticks</code></td><td>DURATION</td><td>是</td><td>—</td><td>持续时间；支持 <code>20t</code>、<code>1s</code>、<code>1000ms</code>，纯数字按 tick 处理。</td></tr><tr><td><code>stack_mode</code></td><td>STRING</td><td>否</td><td>属性定义的 <code>temporary_stack_mode</code></td><td>与组内同属性已有效果的合并方式：<code>REPLACE</code> 覆盖，<code>STACK</code> 数值与剩余时间相加。写入未声明的值以 <code>INVALID_CONFIG</code> 失败。</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_add effect_id=forge_bonus attribute=physical_attack value=12 duration_ticks=10s&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_set effect_id=arena_buff attribute=physical_attack value=30 duration_ticks=200t&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_add effect_id=forge_bonus attribute=physical_attack value=3 duration_ticks=10s stack_mode=STACK&#39;</span></span></code></pre></div><h3 id="attribute-remove" tabindex="-1">attribute_remove <a class="header-anchor" href="#attribute-remove" aria-label="Permalink to “attribute_remove”">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>effect_id</code></td><td>STRING</td><td>是</td><td>—</td><td>要清理的效果组 ID；该组内全部属性一起移除。</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_remove effect_id=arena_buff&#39;</span></span></code></pre></div><p>三个段的 <code>effect_id</code> 与 <code>attribute</code> 都会做 id 归一化。<code>effect_id</code> 为空时以 <code>INVALID_CONFIG</code> 失败；目标不是生物实体时以 <code>not_living_entity</code> 跳过（非玩家生物同样可用）。目标身上没有该组时以 <code>skipped</code> 而非成功返回。成功时输出 <code>effect_id</code>、<code>attribute</code>、<code>value</code>、<code>duration_ticks</code>、<code>status</code>、<code>affected_count</code>、<code>existed</code>、<code>remaining_ticks</code>，其中 <code>status</code> 取 <code>APPLIED</code> / <code>REPLACED</code> / <code>STACKED</code> / <code>REMOVED</code>。</p><h2 id="资源" tabindex="-1">资源 <a class="header-anchor" href="#资源" aria-label="Permalink to “资源”">​</a></h2><p>四个资源段会通过 EmakiAttribute 的资源同步边界修改玩家资源当前值。它们共用同一组参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>resource</code></td><td>STRING</td><td>是</td><td>—</td><td>资源 ID，如 <code>health</code>、<code>mana</code>。</td></tr><tr><td><code>amount</code></td><td>DOUBLE</td><td>是</td><td>—</td><td>操作数量。</td></tr></tbody></table><table tabindex="0"><thead><tr><th>段 ID</th><th>计算方式</th></tr></thead><tbody><tr><td><code>attribute_resource_add</code></td><td>当前值 + <code>amount</code></td></tr><tr><td><code>attribute_resource_set</code></td><td>直接设为 <code>amount</code></td></tr><tr><td><code>attribute_resource_remove</code></td><td>当前值 - <code>amount</code>，最低为 0</td></tr><tr><td><code>attribute_resource_consume</code></td><td>与 <code>attribute_resource_remove</code> 完全相同</td></tr></tbody></table><p><code>attribute_resource_consume</code> 与 <code>attribute_resource_remove</code> 的算式一致，保留两个 id 是因为已有配置按名字引用它们；两者共用同一份实现。</p><p>最终值仍会按资源定义的同步规则截断，所以 <code>add</code> 不会超过上限。</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_resource_add resource=mana amount=10&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_resource_set resource=health amount=20&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_resource_remove resource=health amount=5&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_resource_consume resource=mana amount=20&#39;</span></span></code></pre></div><p><code>resource</code> 会做 id 归一化；指向未加载的资源时以 <code>INVALID_CONFIG</code> 失败。成功时输出 <code>resource</code>、<code>operation</code>、<code>amount</code>、<code>old_value</code>、<code>new_value</code>、<code>current_max</code>。</p><h2 id="标签限时属性" tabindex="-1">标签限时属性 <a class="header-anchor" href="#标签限时属性" aria-label="Permalink to “标签限时属性”">​</a></h2><p>标签指向一组配置在一起的属性，所以一次调用就能施加整套增益而不必逐项列出。</p><h3 id="attribute-tag-add" tabindex="-1">attribute_tag_add <a class="header-anchor" href="#attribute-tag-add" aria-label="Permalink to “attribute_tag_add”">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>tag</code></td><td>STRING</td><td>是</td><td>—</td><td>属性标签，不区分大小写。</td></tr><tr><td><code>value</code></td><td>DOUBLE</td><td>是</td><td>—</td><td>对每个命中属性施加的修饰值。</td></tr><tr><td><code>duration_ticks</code></td><td>DURATION</td><td>是</td><td>—</td><td>持续时间。</td></tr><tr><td><code>effect_prefix</code></td><td>STRING</td><td>否</td><td><code>tag:&lt;tag&gt;</code></td><td>整套命中属性归入的<strong>效果组 ID</strong>；为空时用 <code>tag:&lt;标签&gt;</code>。</td></tr><tr><td><code>stack_mode</code></td><td>STRING</td><td>否</td><td><code>&quot;&quot;</code></td><td>叠加模式：<code>REPLACE</code> 或 <code>STACK</code>。为空时各属性用自身的 <code>temporary_stack_mode</code>；写了无法识别的值以 <code>INVALID_CONFIG</code> 失败。</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_tag_add tag=DEBUFF value=-5 duration_ticks=5s effect_prefix=poison stack_mode=REPLACE&#39;</span></span></code></pre></div><p>上例命中的全部属性都进 <code>poison</code> 这一个组，因此可以直接用 <code>attribute_remove effect_id=poison</code> 整组清掉。</p><h3 id="attribute-tag-remove-attribute-tag-clear" tabindex="-1">attribute_tag_remove / attribute_tag_clear <a class="header-anchor" href="#attribute-tag-remove-attribute-tag-clear" aria-label="Permalink to “attribute_tag_remove / attribute_tag_clear”">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>tag</code></td><td>STRING</td><td>是</td><td>—</td><td>要移除限时属性的属性标签。</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_tag_remove tag=DEBUFF&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_tag_clear tag=BUFF&#39;</span></span></code></pre></div><p>这两个段行为完全一致，都是按标签移除。这个重复是从旧实现保留下来的：判断 <code>clear</code> 原本想做什么（大概是清掉全部标签）会改变现有配置可能依赖的行为，所以没有动它。</p><p><code>tag</code> 为空时以 <code>INVALID_CONFIG</code> 失败；没有任何属性带该标签、或目标身上没有对应效果时以 <code>skipped</code> 返回而不再报成功。三个段成功时都输出 <code>tag</code>、<code>effect_id</code>、<code>status</code> 与 <code>count</code>（命中并处理的属性条数）。</p><h2 id="同步" tabindex="-1">同步 <a class="header-anchor" href="#同步" aria-label="Permalink to “同步”">​</a></h2><p>两个段都只有一个参数，区别在默认值和是否清缓存。</p><table tabindex="0"><thead><tr><th>段 ID</th><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>attribute_sync</code></td><td><code>all</code></td><td>BOOLEAN</td><td><code>false</code></td><td>重算属性值，不清缓存。默认只处理目标。</td></tr><tr><td><code>attribute_refresh</code></td><td><code>all</code></td><td>BOOLEAN</td><td><code>true</code></td><td>先清掉模块缓存再重算，是改完属性配置后该跑的段。默认处理全部在线玩家。</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # 只同步自己</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_sync&#39;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # 同步全部在线玩家，不需要目标，可省略 source</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;attribute_sync all=true&#39;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # 配置改完后清缓存并全服重算</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;attribute_refresh&#39;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # 只对自己清缓存重算</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_refresh all=false&#39;</span></span></code></pre></div><p>这两个段的目标要求是 <code>OPTIONAL</code> 而不是 <code>REQUIRED_ENTITY</code>，因为 <code>all=true</code> 根本不需要目标；<code>all=false</code> 的路径自己检查玩家，拿不到玩家时跳过。</p><p>它们也是本模块唯一线程域随参数变化的段：<code>all=true</code> 要遍历在线玩家列表，跑在服务端全局域上；<code>all=false</code> 只碰单个实体。<code>all</code> 的值写成占位符时无法在规划期读出，此时按该段自己的默认值判定域，所以 <code>attribute_refresh</code> 会按全局域规划。</p><p>成功时输出 <code>all</code>，<code>all=false</code> 时还带上 <code>player</code>。</p><h2 id="使用提示" tabindex="-1">使用提示 <a class="header-anchor" href="#使用提示" aria-label="Permalink to “使用提示”">​</a></h2><ul><li>除 <code>attribute_sync all=true</code> 与 <code>attribute_refresh all=true</code> 外，本页段都需要玩家目标。</li><li>如果需要让 MythicMobs 技能直接对目标生物添加或清除限时属性，请使用 <a href="./mythic.html">MythicMobs 集成</a> 中的 <code>emaki_attribute_add</code>、<code>emaki_attribute_remove</code>、<code>emaki_attribute_add_tag</code>、<code>emaki_attribute_clear_tag</code>。那些是 MythicMobs 机制，不是本页的 CoreLib 段。</li><li><code>duration_ticks</code> 使用 CoreLib DURATION 解析，<code>20t</code>、<code>1s</code>、<code>1000ms</code> 都可用；纯数字按 tick 处理。</li><li>相关服务尚未就绪时，段以 <code>MISSING_CONTEXT</code> 失败而不是静默跳过。</li></ul>`,53)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};